INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(20701, 'Daniel 3:9', 'Daniel', 3, 9, '&nbsp;هغوئ نبوکدنضر بادشاه ته ووئيل چې، ”اے بادشاه، تۀ دې د تل دپاره ژوندے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20702, 'Daniel 3:10', 'Daniel', 3, 10, '&nbsp;اے بادشاه سلامت، تاسو يو فرمان جارى کړے دے، هغه دا چې هر څوک چې د بيګل، شپيلۍ، رباب، بينجو، سريندې، ستار او هر قسمه موسيقۍ او سازونو آواز واورى هغوئ دې د سرو زرو مجسمې ته سجده وکړى او د هغې عبادت دې وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20703, 'Daniel 3:11', 'Daniel', 3, 11, '&nbsp;او هر څوک چې دې مجسمې ته سجده ونۀ کړى او د هغې عبادت ونۀ کړى، نو هغه به د بل شوې اور بټۍ ته ضرور وغورزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20704, 'Daniel 3:12', 'Daniel', 3, 12, '&nbsp;خو اے بادشاه سلامت، دلته يو څو يهوديان دى څوک چې تا د بابل په صوبې باندې مشران مقرر کړى دى، شدرک، ميشک او عبدنجو، څوک چې تا له توجو نۀ درکوى. نۀ هغوئ ستا د معبودانو خِدمت کوى او نۀ د هغه سرو زرو د مجسمې عبادت کوى کومه چې تا ودرولې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20705, 'Daniel 3:13', 'Daniel', 3, 13, '&nbsp;نو بيا په دې باندې بادشاه ډېر غصه شو او حکم يې وکړو چې سمدستى شدرک، ميشک، او عبدنجو ما ته حاضر کړئ. نو دا کسان بادشاه له راوستلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20706, 'Daniel 3:14', 'Daniel', 3, 14, '&nbsp;نو بيا نبوکدنضر هغوئ ته ووئيل، ”شدرک، ميشک او عبدنجو ولې دا خبره رښتيا ده چې تاسو زما د معبودانو خِدمت او د هغه سرو زرو د مجسمې عبادت نۀ کوئ کومه چې ما ودرولې ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20707, 'Daniel 3:15', 'Daniel', 3, 15, '&nbsp;اوس کله چې تاسو د بيګل، شپيلۍ، رباب، بينجو، سريندې، ستار او هر قسمه موسيقۍ او سازونو آواز واورئ، نو کۀ چرې تاسو دې ته تيار يئ چې هغه د سرو زرو د مجسمې په وړاندې ټيټ شئ او د هغې عبادت وکړئ کومه چې ما جوړه کړې ده، نو ډېره ښۀ ده. خو کۀ چرې تاسو د هغې عبادت ونۀ کړئ نو تاسو به سمدستى د اور بټۍ ته وغورزولے شئ. نو کوم يو معبود به تاسو زما د لاسه خلاص کړى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20708, 'Daniel 3:16', 'Daniel', 3, 16, '&nbsp;شدرک، ميشک او عبدنجو بادشاه ته جواب ورکړو، ”اے نبوکدنضره، مونږ ته د دې ضرورت نشته چې ستا نه په دې معامله کښې د خپل ځان ساتنه وکړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20709, 'Daniel 3:17', 'Daniel', 3, 17, '&nbsp;اے بادشاه کۀ چرې مونږ د بل شوې اور بټۍ ته وغورزولے شُو، نو د کوم خُدائ پاک چې مونږ خِدمت کوُو هغه دا کولے شى چې مونږ د هغې نه وساتى، او هغه به مونږ ستا د لاسونو نه بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20710, 'Daniel 3:18', 'Daniel', 3, 18, '&nbsp;اے بادشاه سلامت، خو کۀ چرې هغه مونږ ستا نه بچ هم نۀ کړى، خو تۀ په دې پوهه شه چې مونږ به نۀ ستا د معبودانو عبادت او نۀ د هغه سرو زرو د مجسمې عبادت وکړُو کومه چې تا ودرولې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20711, 'Daniel 3:19', 'Daniel', 3, 19, '&nbsp;نو بيا نبوکدنضر شدرک، ميشک او عبدنجو ته ډېر سخت غصه شو، او د غصې نه د هغۀ رنګ تک سور شو. او هغۀ حکم وکړو چې هغه د اور بټۍ د پخوا نه اووۀ ځله زياته ګرمه کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20712, 'Daniel 3:20', 'Daniel', 3, 20, '&nbsp;او هغۀ په خپل فوج کښې څو تکړه کسانو ته حکم وکړو چې شدرک، ميشک او عبدنجو کلک وتړئ او په بټۍ کښې يې د اور لمبو ته وغورزوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20713, 'Daniel 3:21', 'Daniel', 3, 21, '&nbsp;نو بيا هغوئ هغه درې واړه کسان د خپلو قميصونو، پرتوګونو، چوغو او پټکو سره وتړل او د اور لمبو ته يې په بټۍ کښې وروغورزول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20714, 'Daniel 3:22', 'Daniel', 3, 22, '&nbsp;خو د بادشاه حکم ډېر زورَور وو او بټۍ ډېره زياته ګرمه شوې وه نو ځکه د اور شغلو هغه فوجيان وسوزول او مړۀ يې کړل چا چې شدرک، ميشک او عبدنجو د اور په بټۍ کښې وغورزول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20715, 'Daniel 3:23', 'Daniel', 3, 23, '&nbsp;نو دا درې کسان کلک تړلے شوى وُو او د اور بټۍ کښې يې وغورزول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20716, 'Daniel 3:24', 'Daniel', 3, 24, '&nbsp;سمدستى په حېرانتيا سره نبوکدنضر راپاڅېدو او هغۀ د خپلو مشيرانو نه تپوس وکړو، ”ولې مونږ درې کسان نۀ وُو تړلى او په دې بټۍ کښې مو نۀ وُو غورزولى څۀ؟“ په جواب کښې هغوئ ورته ووئيل چې، ”آو جې، اے بادشاه سلامت.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20717, 'Daniel 3:25', 'Daniel', 3, 25, '&nbsp;هغۀ ووئيل چې، ”خو وګورئ، زۀ درې نه، بلکې څلور کسان وينم چې په اور کښې ګرځى، چې نۀ تړلے شوى دى او نۀ ورته څۀ نقصان رسېدلے دے او څلورم کس لکه د مقدسې فرښتې په شان ښکارى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20718, 'Daniel 3:26', 'Daniel', 3, 26, '&nbsp;نو بيا نبوکدنضر د اور د بټۍ خولې ته نزدې ورغلو او آواز ‎يې ورکړو، ”شدرک، ميشک او عبدنجو، د خُدائ تعالىٰ خِدمتګارانو، بهر راوځئ. دلته راشئ.“ نو شدرک، ميشک او عبدنجو د اور نه بهر راووتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20719, 'Daniel 3:27', 'Daniel', 3, 27, '&nbsp;نو بيا لوئ آفسران، سرکارى کسان، حکمرانان، او مشيران د هغوئ نه ګېرچاپېره راټول شول او وې ليدل چې اور بلکل د هغوئ بدن ته څۀ نقصان نۀ دے ورکړے، او نۀ د هغوئ د سر وېښتۀ راګونجى شوى دى، او د هغوئ چُوغې هم نۀ دى سوزېدلې، او د هغوئ د بدن نه د اور بوئ هم نۀ تلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20720, 'Daniel 3:28', 'Daniel', 3, 28, '&nbsp;نو بيا نبوکدنضر ووئيل، ”د شدرک، ميشک او د عبدنجو د خُدائ پاک ثنا‌ء دې وى چا چې خپله فرښته راولېږله او خپل خِدمتګاران يې بچ کړل. د هغوئ په هغۀ باندې ايمان وو او زما حکم يې د ‎پښو لاندې کړو او هغوئ دې ته تيار وُو چې د خُدائ پاک دپاره خپل ژوند د لاسه ورکړى نۀ دا چې د هغۀ په ځائ د بل معبود خِدمت او عبادت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20721, 'Daniel 3:29', 'Daniel', 3, 29, '&nbsp;نو په دې وجه زۀ دا حکم جارى کوم چې د ټولو خلقو او قومونو او د هرې ژبې خلق کۀ چرې هغوئ د شدرک، ميشک او عبدنجو د خُدائ پاک خلاف څۀ ووائى نو هغوئ به ټوټې ټوټې شى او د هغوئ کورونه به تباه کړے شى، ځکه چې بل يو معبود هم داسې نشته چې څوک داسې بچ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20722, 'Daniel 3:30', 'Daniel', 3, 30, '&nbsp;نو بيا بادشاه شدرک، ميشک او عبدنجو ته د بابل په صوبه کښې نور هم اوچت مقام ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20723, 'Daniel 4:1', 'Daniel', 4, 1, '&nbsp;نبوکدنضر بادشاه د دُنيا ټولو خلقو، ټولو قومونو، او ټولو ژبو ويوونکو ته دا پېغام ورولېږلو چې، په خير اوسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20724, 'Daniel 4:2', 'Daniel', 4, 2, '&nbsp;زۀ غواړم چې تاسو ته د هغه معجزو او حېرانونکو نښو په حقله خبرې وکړم کومې معجزې چې خُدائ تعالىٰ زما دپاره کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20725, 'Daniel 4:3', 'Daniel', 4, 3, '&nbsp;د هغۀ معجزې څومره لوئ دى، او د هغۀ عجائبات څومره طاقتور دى. د هغۀ بادشاهى تر ابده پورې ده، او د هغۀ بادشاهى نسل در نسل پورې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20726, 'Daniel 4:4', 'Daniel', 4, 4, '&nbsp;ما نبوکدنضر په خپل محل کښې په آرام او عېش عشرت سره ژوند کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20727, 'Daniel 4:5', 'Daniel', 4, 5, '&nbsp;ما يو خوب وليدو کوم چې زۀ ويرولم. کله چې زۀ په خپل کټ کښې پروت وم، نو کومه رويا او تصور چې زما په خيال کښې راغلو نو هغې زۀ ډېر زيات ويرولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20728, 'Daniel 4:6', 'Daniel', 4, 6, '&nbsp;نو ما بيا حکم وکړو چې د بابل ټول هوښيار خلق راوغواړئ چې زما د خوب تعبير وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20729, 'Daniel 4:7', 'Daniel', 4, 7, '&nbsp;نو کله چې جادوګر، فالګر، نجوميان او قسمت معلومونکى راغلل، ما هغوئ ته خوب ووئيلو خو هغوئ د هغې تعبير ما ته ونۀ کړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20730, 'Daniel 4:8', 'Daniel', 4, 8, '&nbsp;خو آخر دانيال زما حضور ته راغلو، او ما ورته خپل خوب بيان کړو. مقدسو معبودانو ورته خاص طاقت ورکړے وو، او ما په هغۀ باندې د خپل معبود بيلطشضر نوم کېښودو. او د معبودانو روح په هغۀ کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20731, 'Daniel 4:9', 'Daniel', 4, 9, '&nbsp;ما ورته ووئيل چې، ”بيلطشضر د جادوګرانو مشره زۀ په دې پوهېږم چې د معبودانو روح په تا کښې دے، او هيڅ راز معلومول ستا دپاره مشکل کار نۀ دے. زما خوب داسې دے، او تۀ يې ما ته تعبير راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20732, 'Daniel 4:10', 'Daniel', 4, 10, '&nbsp;کله چې زۀ په خپل کټ کښې اودۀ وم ما دا خوب وليدلو، ما وليدل، زما په وړاندې د زمکې په مينځ کښې يوه ونه ولاړه وه. او هغه ډېره زياته اوچته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20733, 'Daniel 4:11', 'Daniel', 4, 11, '&nbsp;دا ونه ډېره غټه او لوړه او طاقتوره شوه او سر يې د آسمان سره ولګېدو، او دا به د ټولې دُنيا د بل سر نه ښکارېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20734, 'Daniel 4:12', 'Daniel', 4, 12, '&nbsp;د هغې پاڼې ښکلې وې، او مېوه يې ډېره وه، او په دې کښې د هر چا خوراک وو. او د هغې لاندې د مېدان ځناورو د ځان دپاره د پناه ځائ پېدا کړو، او د هوا مارغانو يې په څانګو کښې ځان له جالې جوړې کړې، او هغې نه هر يو مخلوق ته خوراک مِلاوېدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20735, 'Daniel 4:13', 'Daniel', 4, 13, '&nbsp;کله چې ما لا په خوب کښې د دې رويا په حقله سوچ کولو، نو ومې ليدل چې د آسمان نه يوه مقدسه فرښته راکوزېده، چې اخوا ديخوا يې کتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20736, 'Daniel 4:14', 'Daniel', 4, 14, '&nbsp;هغې په زور سره دا اعلان وکړو چې، دا ونه راوغورزوئ او څانګې يې پرې کړئ، د دې پاڼې راوشوکوئ او مېوه يې تس نس کړئ. د دې لاندې ځناور او د څانګو نه يې مارغان وشړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20737, 'Daniel 4:15', 'Daniel', 4, 15, '&nbsp;خو د دې بېخ په زمکه کښې پرېږدئ او د اوسپنې او زېړو پټۍ ترې نه تاو کړئ. او هلته يې په واښو کښې پرېږدئ. نو پرېږدئ چې هغه په پرخه کښې لوند شى او هغه دې په ځنګل کښې د ځناورو سره اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20738, 'Daniel 4:16', 'Daniel', 4, 16, '&nbsp;اووۀ کاله به هغه د انسان عقل نۀ لرى بلکې د هغۀ عقل به د ځناورو وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20739, 'Daniel 4:17', 'Daniel', 4, 17, '&nbsp;د هغه فرښتې د سزا ورکولو فېصله واورولے شوه، ترڅو چې هر يو کس ته د دې پته ولګى چې خُدائ تعالىٰ د انسانانو په بادشاهۍ باندې اختيار لرى او چې هغه چا له وغواړى نو هغۀ له بادشاهى ورکوى، کۀ څۀ هم چې هغه کس ډېر غريب وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20740, 'Daniel 4:18', 'Daniel', 4, 18, '&nbsp;نبوکدنضر بادشاه ووئيل، ”دا هغه خوب دے چې ما وليدلو. نو بيا بيلطشضره، تۀ ما ته د دې تعبير بيان کړه ځکه چې زما يو شاهى مشير هم ما له د دې تعبير نۀ شى راکولے. خو تۀ يې راکولے شې ځکه چې د مقدسو معبودانو روح په تا کښې دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20741, 'Daniel 4:19', 'Daniel', 4, 19, '&nbsp;نو دانيال، چې بل نوم يې بيلطشضر وو، په دې دومره هيبت واخستو چې د څۀ وخت دپاره هيڅ يې هم نۀ شو فرمائيلے، او د هغۀ سوچ هغه وارخطا کړو. نو بادشاه هغۀ ته ووئيل، ”بيلطشضره، په دې خوب او د هغې په مطلب مۀ خفه کېږه.“ خو بيلطشضر ورته په جواب کښې وفرمائيل، ”بادشاه سلامت، زۀ غواړم چې دا خوب او د دې تعبير دې ستا دپاره نه بلکې ستا د دشمنانو دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20742, 'Daniel 4:20', 'Daniel', 4, 20, '&nbsp;هغه ونه چې تا وليدله، کومه چې دومره لوړه وه چې آسمان ته رسېدلې وه او په دُنيا کښې هر چا ته ښکارېدله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20743, 'Daniel 4:21', 'Daniel', 4, 21, '&nbsp;د هغې پاڼې ښائسته وې او مېوه يې دومره زياته وه چې د ټولې دُنيا دپاره کافى وه. ځنګلى ځناورو د دې لاندې آرام کولو او مارغانو به د دې په څانګو کښې جالې جوړولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20744, 'Daniel 4:22', 'Daniel', 4, 22, '&nbsp;اے بادشاه سلامت، تۀ په خپله هغه ونه يې. تۀ ډېر اوچت او مضبوط شوے يې، تۀ دومره لوئ شوے يې چې لويوالے دې تر آسمانه پورې رسېدلے دے او ستا بادشاهت د زمکې د بله سره پورې رسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20745, 'Daniel 4:23', 'Daniel', 4, 23, '&nbsp;اے بادشاه سلامت، تا يوه مقدسه فرښته وليدله، چې د آسمان نه لاندې راکوزېدله او فرمائيل يې چې، دا ونه ووهئ او تباه يې کړئ، خو د هغې تنه او جرړې په زمکه کښې پرېږدئ او د اوسپنې او زېړو په زنځير يې وتړئ او په واښو کښې يې پرېږدئ. او پرېږده چې په پرخه کښې لوند شى، او چې د اوو کالونو پورې د ځنګلى ځناورو په مينځ کښې پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20746, 'Daniel 4:24', 'Daniel', 4, 24, '&nbsp;اے بادشاه سلامت، ستا د خوب تعبير دا دے کومه فېصله چې خُدائ تعالىٰ ستا خلاف کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20747, 'Daniel 4:25', 'Daniel', 4, 25, '&nbsp;تۀ به د خلقو نه يوې خوا ته وشړلے شې او د ځنګلى ځناورو سره به ژوند کوې، تۀ به لکه د څاروو په شان ګياه خورې او د آسمان په پرخه به تر کولے شې. نو بيا به اووۀ کالونه تير شى ترڅو چې تۀ په دې باندې پوهه شې چې صرف خُدائ تعالىٰ د انسانانو په بادشاهت اختيار لرى او هغه چا له يې ورکوى چې چا له يې زړۀ غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20748, 'Daniel 4:26', 'Daniel', 4, 26, '&nbsp;د فرښتې هغه حکم چې د ونې تنه سره د جرړو پرېږدئ نو د هغې مطلب دا دے چې ستا بادشاهى به بيا راشى خو کله چې تاسو آسمانى حکومت ومنئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20749, 'Daniel 4:27', 'Daniel', 4, 27, '&nbsp;بادشاه سلامت، په دې وجه دې زما نصيحت تا ته د منلو وى، د خپلو ګناهونو اعتراف وکړه او هغه په ښو کولو سره پرېږده، او په مظلومانو رحم وکړه او شرارت پرېږده. نو کېدے شى چې په دې کښې به ستا د بادشاهۍ خير قائم پاتې شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20750, 'Daniel 4:28', 'Daniel', 4, 28, '&nbsp;بيا دا هر څۀ په نبوکدنضر بادشاه وشُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20751, 'Daniel 4:29', 'Daniel', 4, 29, '&nbsp;دولس مياشتې وروستو کله چې هغه په بابل کښې د شاهى محل په چت باندې ګرځېدو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20752, 'Daniel 4:30', 'Daniel', 4, 30, '&nbsp;هغۀ ووئيل چې، ”ولې دا هغه لوئ د بابل ښار نۀ دے کوم چې د بادشاهانو د اوسېدو دپاره ما په خپل زور طاقت سره د خپل جلال او شان شوکت د څرګندېدو دپاره آباد کړے دے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20753, 'Daniel 4:31', 'Daniel', 4, 31, '&nbsp;هغه خبره لا د هغۀ په شونډو وه چې د آسمان نه يو آواز راغلو، ”نبوکدنضر بادشاه ستا دپاره دا حکم دے چې، ستا نه هغه شاهى اختيارات واخستلے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20754, 'Daniel 4:32', 'Daniel', 4, 32, '&nbsp;تۀ به د خلقو نه وشړلے شې او د ځنګلى ځناورو سره به اوسېږې، تۀ به لکه د څاروو په شان ګياه خورې. په دې به اووۀ کالونه تير شې ترڅو چې تۀ په دې باندې پوهه شې چې خُدائ تعالىٰ د انسانانو په بادشاهت اختيار لرى او هغه چا له يې ورکوى چې چا له يې زړۀ غواړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20755, 'Daniel 4:33', 'Daniel', 4, 33, '&nbsp;نو سمدستى هغه څۀ پوره شُو څۀ چې د نبوکدنضر په حقله وئيلى شوى وُو. هغه د خلقو د مينځ نه وشړلے شو او د ځناورو په شان يې ګياه وخوړله. د هغۀ په بدن پرخه ورېدله تر هغې پورې د هغۀ وېښتۀ لکه د شاهين د بڼو په شان لوئ شُو او د هغۀ نوکونه لکه د مارغانو د پنجو په شان اوږدۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20756, 'Daniel 4:34', 'Daniel', 4, 34, '&nbsp;د اوو کالونو نه وروستو، ما نبوکدنضر خپلې سترګې د آسمان طرف ته اوچتې کړې، او زما عقل دوباره بحال شو. او ما د خُدائ تعالىٰ ثناء صِفت ادا کړو، او د هغۀ احترام او جلال مې بيان کړو څوک چې د تل دپاره ژوندے دے. د هغۀ بادشاهى تر ابده پورې ده، او د هغۀ بادشاهى نسل در نسل پورې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20757, 'Daniel 4:35', 'Daniel', 4, 35, '&nbsp;د هغۀ په مقابل کښې د زمکې ټول خلق هيڅ نۀ دى. هغه د آسمانى فرښتو او د زمکې د خلقو سره چې څۀ غواړى هغه کوى. د هغۀ لاس هيڅوک نۀ شى نيولے او نۀ ورته څوک دا وئيلے شى چې، ”تا څۀ وکړل؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20758, 'Daniel 4:36', 'Daniel', 4, 36, '&nbsp;په هم هغه وخت کښې کله چې زما عقل کار شروع کړو، نو زما عزت او شان و شوکت ما ته د خپلې بادشاهۍ دپاره واپس مِلاو شو او زما مشيرانو او آفسرانو ما ته حلف راکړو، زۀ په خپل تخت باندې دوباره کښېناستلم. او د پخوا نه زما عزت نور هم زيات شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20759, 'Daniel 4:37', 'Daniel', 4, 37, '&nbsp;نو اوس، زۀ نبوکدنضر، د آسمان د بادشاه ثناء صِفت او لوئى بيانوم، ځکه څۀ چې هغه کوى هغه صحيح دى او د هغۀ ټول کارونه د اِنصاف دى. او هغوئ څوک چې کبر او لوئى کوى نو هغه يې عاجز کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20760, 'Daniel 5:1', 'Daniel', 5, 1, '&nbsp;يوه ورځ بيلشضر بادشاه يوه لويه مېلمستيا تياره کړه او د خپلو آفسرانو نه يې زر کسان راوغوښتل او د هغوئ سره يې يوځائ مے وڅښل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20761, 'Daniel 5:2', 'Daniel', 5, 2, '&nbsp;کله چې بيلشضر خپل مے څښل، نو هغۀ حکم وکړو چې هغه د سرو زرو او سپينو زرو جامونه او پيالۍ راوړئ کومې چې د هغۀ پلار نبوکدنضر په يروشلم کښې د مالِک خُدائ د کور نه راوړې وې، چې بادشاه او د هغۀ آفسران، د هغۀ ښځې او د هغۀ وينځې په کښې مے وڅښى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20762, 'Daniel 5:3', 'Daniel', 5, 3, '&nbsp;نو بيا هغوئ د سرو زرو جامونه او پيالۍ راوړې کومې چې په يروشلم کښې د خُدائ پاک د کور نه راوړلے شوې وې، او بادشاه او د هغۀ آفسرانو، د هغۀ ښځو او د هغۀ وينځو په هغو کښې وڅښل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20763, 'Daniel 5:4', 'Daniel', 5, 4, '&nbsp;کله چې هغوئ مے څښل، نو بيا هغوئ د سرو زرو، سپينو زرو، پيتلو، اوسپنو، د لرګى او د کاڼو نه د جوړو شوو معبودانو ثناء صِفت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20764, 'Daniel 5:5', 'Daniel', 5, 5, '&nbsp;او ناګهانه د انسان د لاس ګوتې راښکاره شوې او د شاهى محل د دېوال په پلستر باندې د شمعدان سره نزدې ليکل وکړل. کله چې هغه لاس ليکل کول نو بادشاه په خپله هغه وليدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20765, 'Daniel 5:6', 'Daniel', 5, 6, '&nbsp;د هغۀ رنګ د يرې نه تک زېړ شو او دومره يرېدلے وو چې د پښو د رپېدو په وجه په ځائ ودرېدلے نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20766, 'Daniel 5:7', 'Daniel', 5, 7, '&nbsp;نو بادشاه په تېزه آواز وکړو چې جادوګر، فالګر او نجوميان راوغواړئ. نو د بابل دې هوښيارو سړو ته بادشاه ووئيل چې، ”هر څوک چې دا ليکلے شوى الفاظ ولولى او د هغې مطلب راته بيان کړى نو هغۀ ته به کاسنى چُوغه د عزت دپاره ورواغوستلے شى او د هغۀ په غاړه کښې به د سرو زرو هار واچولے شى، او په بادشاهۍ کښې به ورته درېم مقام مِلاو شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20767, 'Daniel 5:8', 'Daniel', 5, 8, '&nbsp;نو بيا د بادشاه ټول هوښياران راغلل، خو هغوئ هغه ليکل ونۀ شُو لوستلے او نۀ يې بادشاه ته دا وئيلے شُو چې د دې څۀ مطلب دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20768, 'Daniel 5:9', 'Daniel', 5, 9, '&nbsp;نو بيا بيلشضر بادشاه نور هم يرې واخستو او د هغۀ رنګ نور هم زېړ شو. او د هغۀ ټول آفسران هم پرېشانه شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20769, 'Daniel 5:10', 'Daniel', 5, 10, '&nbsp;خو کله چې د بادشاه مور د بادشاه او د هغۀ د مشيرانو شور شرابه واورېده، نو هغه د مېلمنو هال ته راننوتله. هغې ووئيل چې، ”اے بادشاه سلامت تۀ دې د تل دپاره ژوندے يې. مۀ وارخطا کېږه، ډېر مۀ زېړېږه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20770, 'Daniel 5:11', 'Daniel', 5, 11, '&nbsp;ستا په بادشاهۍ کښې يو سړے دے چې په هغۀ کښې د پاکو معبودانو روح دے. ستا د پلار په زمانه کښې په هغۀ کښې د معبودانو په شان عقل، حکمت او پوهه ښکاره شوه. نبوکدنضر بادشاه ستا پلار هغه د جادوګرو، فالګرو، نجوميانو او پېشګويانو والا مشر مقرر کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20771, 'Daniel 5:12', 'Daniel', 5, 12, '&nbsp;دا سړے دانيال، چا ته چې بادشاه بيلطشضر نوم ورکړو، بې‌شانه قابليت او پوهه لرى، او هغه د خوبونو په تعبير، د مشکلو دوڼو په حل کولو او د راز په خبرو څرګندولو کښې تکړه او ماهِر دے. نو دانيال راوغواړه، هغه به درته ووائى چې د دې ليکلو مطلب څۀ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20772, 'Daniel 5:13', 'Daniel', 5, 13, '&nbsp;نو بيا دانيال د بادشاه حضور ته راوستلے شو، او بادشاه هغۀ ته ووئيل، ”تۀ هغه دانيال يې څۀ، څوک چې زما پلار نبوکدنضر بادشاه د يهوداه د جلاوطنو سره د يهوداه نه دلته راوستے وو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20773, 'Daniel 5:14', 'Daniel', 5, 14, '&nbsp;ما اورېدلى دى چې په تا کښې د خُدايانو علم دے، او ستا عقل، پوهه او خاص حِکمت ډېر لوئ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20774, 'Daniel 5:15', 'Daniel', 5, 15, '&nbsp;زما په وړاندې هوښياران او جادوګران راوستلے شوى وُو چې دا ليکلے شوى الفاظ ولولى او ما ته يې مطلب بيان کړى، خو هغوئ د دې مطلب بيان نۀ کړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20775, 'Daniel 5:16', 'Daniel', 5, 16, '&nbsp;خو اوس ما دا اورېدلى دى چې تۀ تعبير ورکولے شې او مشکلې مسئلې حل کولے شې. کۀ تۀ دا ليکل لوستلے شې او ما ته د دې مطلب بيانولے شې، نو ستا د عزت دپاره به تا ته کاسنى شاهى چُوغه درواغوستلے شى او ستا په غاړه کښې به د سرو زرو هار واچولے شى، او په بادشاهۍ کښې به درته درېم لوئ مقام درکړے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20776, 'Daniel 5:17', 'Daniel', 5, 17, '&nbsp;نو دانيال بادشاه ته جواب ورکړو، ”قربان تحفې دې بل چا له ورکړه او يا يې ځان سره کړه. خو بيا به هم زۀ دا ليکل بادشاه ته ولولم او هغۀ ته به يې مطلب بيان کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20777, 'Daniel 5:18', 'Daniel', 5, 18, '&nbsp;اے بادشاه سلامت، خُدائ تعالىٰ ستا پلار نبوکدنضر ته بادشاهت، لويوالے، جلال او شان و شوکت ورکړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20778, 'Daniel 5:19', 'Daniel', 5, 19, '&nbsp;هغۀ، هغۀ له ډېر اوچت مقام ورکړے وو نو په دې وجه د ټولو خلقو د ټولو قومونو، او ټولو ژبو خلق د هغۀ په وړاندې د يرې نه ريږدېدل. څوک به چې هغۀ مړ کول غوښتل نو مړ به يې کړو، څوک به يې چې ژوندے پرېښودل غوښتل نو هغه به يې ژوندے پرېښودو، او چا ته به يې چې ترقى ورکول غوښتل نو هغۀ له به يې ترقى ورکړه، او څوک به يې چې عاجز کول غوښتل هغه به يې عاجز کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20779, 'Daniel 5:20', 'Daniel', 5, 20, '&nbsp;خو کله چې د هغۀ زړۀ مغروره شو، او کبر يې اختيار کړو، نو هغه د خپلې بادشاهۍ تخت نه کوز کړے شو او هغه د خپل عزت نه محروم کړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20780, 'Daniel 5:21', 'Daniel', 5, 21, '&nbsp;هغه د بنيادمو د مينځ نه وشړلے شو او هغۀ ته د ځناورو عقل ورکړے شو، او هغه د ځنګلى خرو سره اوسېدو. هغۀ لکه د څاروى په شان ګياه وخوړه، او د هغۀ بدن د آسمان په پرخه باندې تر شو، ترڅو چې هغۀ دا وپېژندل چې خُدائ تعالىٰ د بنيادمو په بادشاهت باندې اختيار لرى او هغه چا له يې ورکوى چې چا له يې زړۀ غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20781, 'Daniel 5:22', 'Daniel', 5, 22, '&nbsp;خو تا د هغۀ زويه بيلشضره، خپل ځان د هغۀ په وړاندې عاجز نۀ کړے شو، باوجود د دې چې تۀ په دې هر څۀ باندې خبر وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20782, 'Daniel 5:23', 'Daniel', 5, 23, '&nbsp;بلکې، تا خپل ځان د آسمانى مالِک په خلاف راپورته کړو. د هغۀ د کور جامونه او پيالۍ ستا په وړاندې راوړلے شوى دى. تا او ستا آفسرانو، ستا ښځو، او ستا وينځو په هغې کښې مے وڅښل. تا د سرو زرو او سپينو زرو، د زېړو، د اوسپنې، لرګى او د کاڼو نه د جوړو شوو معبودانو ثناء صِفت وکړو، څوک چې نۀ ليدلے شى او نۀ اورېدلے شى او نۀ پوهيږى. خو تا د هغه مالِک خُدائ عزت ونۀ کړو د چا په لاس کښې چې ستا ژوند او ستا ټولې لارې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20783, 'Daniel 5:24', 'Daniel', 5, 24, '&nbsp;نو په دې وجه خُدائ پاک لاس راولېږلو کوم چې دا پېغام وليکلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20784, 'Daniel 5:25', 'Daniel', 5, 25, '&nbsp;دا هغه پېغام دے کوم چې ليکلے شوے وو، منې، منې تقيل، فرسين.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20785, 'Daniel 5:26', 'Daniel', 5, 26, '&nbsp;د دې الفاظو مطلب دا دے. منې، د دې مطلب دے شمېر، خُدائ پاک ستا د بادشاهۍ ورځې شمېرلې دى او هغه يې ختمې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20786, 'Daniel 5:27', 'Daniel', 5, 27, '&nbsp;تقيل، مطلب دے وزن، تۀ په تله باندې وتللے شوې او په وزن ډېر سپک وختلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20787, 'Daniel 5:28', 'Daniel', 5, 28, '&nbsp;د فرسين، معنىٰ دا ده چې تقسيم، ستا بادشاهى تقسيم شوې ده او هغه ميديانو او فارسيانو ته ورکړے شوې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20788, 'Daniel 5:29', 'Daniel', 5, 29, '&nbsp;نو بيا د بيلشضر په حکم، دانيال ته کاسنى رنګ چُوغه ورواغوستلے شوه، د هغۀ په غاړه کښې يې د سرو زرو هار ورواچولو، او په بادشاهۍ کښې هغه د درېم اوچت مقام په توګه اعلان کړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20789, 'Daniel 5:30', 'Daniel', 5, 30, '&nbsp;نو په هم هغه شپه بيلشضر د بابل بادشاه ووژلے شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20790, 'Daniel 5:31', 'Daniel', 5, 31, '&nbsp;داريوس ميدى چې د دوو شپيتو کالو وو نو بادشاهى يې ونيوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20791, 'Daniel 6:1', 'Daniel', 6, 1, '&nbsp;داريوس دا فېصله وکړه چې ټوله بادشاهى په يو سل او شل صوبو باندې تقسيم کړى، او هغۀ لوئ آفسران مقرر کړل چې په هره صوبه حکمرانى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20792, 'Daniel 6:2', 'Daniel', 6, 2, '&nbsp;بادشاه دانيال او دوه نور کسان په دې آفسرانو سر پرست مقرر کړل چې په آفسرانو او د بادشاه په ګټو باندې نظر وساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20793, 'Daniel 6:3', 'Daniel', 6, 3, '&nbsp;دانيال زر دا ثابته کړه چې هغه د نورو وزيرانو او لوئ آفسرانو نه ډېر قابل دے. نو بيا ځکه بادشاه دا فېصله وکړه چې هغه په ټوله بادشاهۍ باندې حاکِم مقرر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20794, 'Daniel 6:4', 'Daniel', 6, 4, '&nbsp;نو په دې وجه نور وزيران او لوئ آفسران په دې لټون کښې شُو چې د هغۀ په حکومتى انتظام کښې څۀ داسې غلطى پېدا کړى. خو هغوئ څۀ داسې هيڅ څيز د هغۀ خلاف پېدا نۀ کړلو چې هغه پرې ملامته کړى، ځکه چې هغه ډېر ايماندار وو او هيڅ قسم غلطى او بې‌ايمانى يې نۀ کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20795, 'Daniel 6:5', 'Daniel', 6, 5, '&nbsp;آخر هغه کسانو دا ووئيل چې، ”دې طريقې سره به مونږ په دانيال هيڅ قِسمه اِلزام ونۀ لګولے شُو. خو يوه خبر ده چې د اِلزام باعث جوړېدے شى يعنې د هغۀ د خُدائ پاک د شريعت په حقله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20796, 'Daniel 6:6', 'Daniel', 6, 6, '&nbsp;نو بيا وزيران او لوئ آفسران په يو ځائ بادشاه له ورغلل او ورته يې ووئيل چې، ”داريوس بادشاه دې د تل دپاره ژوندے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20797, 'Daniel 6:7', 'Daniel', 6, 7, '&nbsp;مونږ د ټول مُلک شاهى وزيران، آفسران، مشيران، مشران او حاکمان په دې راضى شوى يُو چې بادشاه دې يو فرمان جارى کړى او په سختۍ سره دې په هغې عمل وکړے شى چې په راتلونکو دېرشو ورځو کښې هر څوک چې هم ستا نه بغېر د بل معبود يا انسان عبادت وکړى، نو هغه دې د زمرو په غار کښې واچولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20798, 'Daniel 6:8', 'Daniel', 6, 8, '&nbsp;نو اوس، اے بادشاه سلامت، دا حکم جارى کړه او مهر پرې ولګوه چې څوک هم دا بدل نۀ کړے شى، لکه د ميديانو او فارسيانو د قانون په مطابق چې نۀ منسوخ کېدونکے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20799, 'Daniel 6:9', 'Daniel', 6, 9, '&nbsp;نو بيا داريوس بادشاه په ليکل شوے فرمان دستخط وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20800, 'Daniel 6:10', 'Daniel', 6, 10, '&nbsp;خو کله چې دانيال په دې خبر شو چې دا فرمان جارى شوے دے، نو هغه په خپل کور کښې بره کوټې ته لاړو چې کړکۍ يې د يروشلم طرف ته کولاو وې. نو هره ورځ به يې درې ځله سجده او دُعا کوله، او د خپل خُدائ پاک شُکر به يې ادا کولو، لکه څنګه چې هغۀ وړاندې کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');